def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    # Count patterns efficiently in one pass
    cc = dd = cd = dc = 0
    opp_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if b == 'C':
                dc += 1
            else:
                dd += 1

    opp_d = n - opp_c
    last_me, last_opp = history[-1]

    # Detect pure defector very early and stop wasting cooperation
    if n >= 3 and opp_d == n and dd == n:
        return 'D'

    # Detect extremely defection-heavy opponents quickly
    if n >= 5 and opp_d >= n - 1 and opp_c <= 1 and opp_d > cc:
        return 'D'

    # Detection of unconditional cooperator: exploit but keep some cooperation
    # to preserve the source of points. In noisy-free setting, DC=5 vs CC=3
    # means a small amount of exploitation is profitable.
    if n >= 6 and opp_d == 0:
        # Test if they cooperate after our defections
        exploited = False
        for i in range(n):
            if history[i][0] == 'D' and history[i][1] == 'C':
                exploited = True
                break
        if exploited:
            # They don't retaliate: exploit more heavily but not exclusively
            if n >= 95:
                return 'D'
            return 'D' if rng.random() < 0.55 else 'C'
        # Untested: probe occasionally
        if n in (6, 12, 18, 24, 30):
            return 'D'
        if n >= 95:
            return 'D'
        return 'C'

    # Now handle the general case with a forgiving tit-for-tat core.
    # If opponent just cooperated, generally cooperate.
    if last_opp == 'C':
        # If opponent has been mostly cooperative but has occasional defections,
        # maintain cooperation; small chance to probe for exploitation.
        if opp_d <= 2 and n > 15:
            if rng.random() < 0.06:
                return 'D'
        return 'C'

    # Opponent defected last round.
    # Determine if this looks like a one-off (noise-like) or a pattern.
    # Count consecutive opponent defections at the tail.
    tail_d = 0
    for a, b in reversed(history):
        if b == 'D':
            tail_d += 1
        else:
            break

    # Long defection streak: stay in defection to avoid being exploited.
    if tail_d >= 3:
        return 'D'

    # Single defection: retaliate once, then forgive if they return to C.
    if tail_d == 1:
        # If opponent has been overwhelmingly cooperative, forgive quickly
        # but still retaliate once to signal.
        if opp_d <= 1 and n >= 4:
            return 'D'
        if opp_d * 4 <= n and n >= 6:
            # Mostly cooperative opponent: retaliate once only
            return 'D'
        # Mixed opponent: retaliate harder
        if opp_d * 2 >= n:
            return 'D' if rng.random() < 0.9 else 'C'
        return 'D'

    # tail_d == 2: retaliate more firmly
    if opp_d * 2 >= n:
        return 'D'
    return 'D' if rng.random() < 0.8 else 'C'
